const HTML_B64 = '';
function b64decode(str){const b=atob(str);const bytes=new Uint8Array(b.length);for(let i=0;i<b.length;i++){bytes[i]=b.charCodeAt(i);}return new TextDecoder().decode(bytes);}
export default {async fetch(request,env,ctx){return new Response(b64decode(HTML_B64),{headers:{'Content-Type':'text/html; charset=UTF-8'}});}};
